-- Song-loading (rainbow) transition backdrop, sampled from the arcade timeline.
local ok, anim = pcall(require, "anim/sampler")
local CLIP = (ok and anim and anim.safe) and anim.safe("anim/loading_song") or nil

SongTransition = {}
SongTransition.__index = SongTransition

local FADE_DELAY, FADE_MS, FADE_OUT_MS = 266.0, 266.0, 133.0
local SCENE_MS = FADE_DELAY + FADE_MS          -- 532 ms: how long each scene shows

local F_IN, F_STOP, F_OUT, F_END = 5, 55, 60, 109
local F_FULL_A, F_FULL_B = 35, 78              -- the full-rainbow window

