local function clamp(v, a, b) if v < a then return a elseif v > b then return b else return v end end

-- read a track field, falling back to `default` when the table is gone
local function track(name, f, field, default)
    if not CLIP then return default end
    local v = CLIP:get(name, f, field)
    if v == nil then return default end
    return v
end

-- 演奏スキップON badge (624x104 pill at (38,54))
local SKIP_BADGE_X, SKIP_BADGE_Y = 38, 54
local SKIP_BADGE_CX = 350            -- 38 + 624/2, the EditText's centre
local SKIP_TEXT_CY  = 109            -- 69 + 80/2, the EditText box's centre
local SKIP_TEXT_SIZE = 30
-- badge.png declares its own (38,54) origin, so pass it back as rest to cancel
local SKIP_REST = { 38, 54 }

local ai_setup   -- defined below (the AI battle's start screens)
local HINT_COUNT, HINT_LAST = 0, nil   -- normal loading: the hint card alternates (arcade: hint block / wash-your-hands card)

function SongTransition.new(title, subtitle, is_second)
    local self = setmetatable({}, SongTransition)
    self.is_second = is_second and true or false
    self.t0   = nil
    self.f    = self.is_second and F_OUT or F_IN
    self.info = 0          -- band / hint opacity, 0..1
    self.rainbow = tex.get_texture("global/rainbow_transition/rainbow_bg")
    self.atlas_c = tex.get_texture("global/rainbow_transition/rainbow_bg_top")
    self.atlas_b = tex.get_texture("global/rainbow_transition/rainbow_bg_bottom")
    self.chara_l = tex.get_texture("global/rainbow_transition/chara_left")
    self.chara_r = tex.get_texture("global/rainbow_transition/chara_right")
    self.hint    = tex.get_texture("global/rainbow_transition/chara_center")
    -- the hint block is baked in Japanese; other languages draw it as text
    local lang = tex.language and tex.language() or "ja"
    if lang ~= "ja" and text and text.create_text then
        local white, black = { 255, 255, 255, 255 }, { 0, 0, 0, 255 }
        self.hint_title = text.create_text("transition_hint_title", white, black, false, 4.0, 2.0, 1.0, "FOT-Seurat_Pro_B.otf")
        self.hint_line1 = text.create_text("transition_hint_line1", white, black, false, 3.0, 2.0, 1.0, "FOT-Seurat_Pro_B.otf")
        self.hint_line2 = text.create_text("transition_hint_line2", white, black, false, 3.0, 2.0, 1.0, "FOT-Seurat_Pro_B.otf")
    end
    -- 演奏スキップON badge
    self.skip_badge = tex.get_texture("loading/skip_badge/badge")
    -- resolved on first draw (skip state isn't ready at construction)
    self.skip_on    = nil
    if text and text.create_raw_text then
        -- built here (not on first draw) so the glyph atlas is ready
        self.skip_text = text.create_raw_text(tex.skin_text("skip_badge_text"), SKIP_TEXT_SIZE,
            { 0, 0, 0, 255 }, { 0, 0, 0, 0 }, false, 0, 2)
    end
    local ai_screen = tex.current_screen and tex.current_screen()
    local ai_tr = tex.ai_transition and tex.ai_transition()
    if tex.ai_transition == nil then ai_tr = ai_screen == "AI_SELECT" or ai_screen == "AI_GAME" end   -- YataiDON's own screens
    if ai_tr then ai_setup(self, title, subtitle) end
    if not self.is_second then HINT_COUNT = HINT_COUNT + 1; HINT_LAST = (HINT_COUNT % 2 == 0) end
    self.wash = HINT_LAST and true or false
    return self
end

-- resolved lazily on first draw, once init_skip() has run
function SongTransition:skip_armed()
    if self.skip_on == nil then
        self.skip_on = (tex.skip_enabled ~= nil) and tex.skip_enabled() or false
    end
    return self.skip_on
end

-- timeline the engine reads (rainbow rise for the title, title fades, done)
local RISE_MS, RISE_DIST = 266.0, 1224  -- 816 at 720p, scaled to 1080p
function SongTransition:state()
    local t = self.t or 0
    local rise = RISE_DIST * clamp(t / RISE_MS, 0, 1) ^ 3
    if self.is_second then
        -- runs the whole scene so the curtains open on the game (frames 79..109)
        return { rainbow_up = rise, fade_out = clamp(1.0 - t / FADE_OUT_MS, 0, 1),
                 finished = t >= SCENE_MS }
    end
    return { rainbow_up = rise, fade = clamp((t - FADE_DELAY) / FADE_MS, 0, 1),
             finished = t >= SCENE_MS }
end

function SongTransition:start() self.t0 = nil end

function SongTransition:update(current_ms, rainbow_up, song_info_fade)
    if not self.t0 then self.t0 = current_ms end
    self.t = current_ms - self.t0
    local t = clamp(self.t, 0, SCENE_MS)
    if self.is_second then
        self.f    = F_OUT + (F_END - F_OUT) * (t / SCENE_MS)
        self.info = clamp(1.0 - t / FADE_OUT_MS, 0, 1)
    else
        self.f    = F_IN + (F_STOP - F_IN) * (t / SCENE_MS)
        -- use the engine's fade so the band tracks the title it draws on top
        self.info = clamp(song_info_fade or ((t - FADE_DELAY) / FADE_MS), 0, 1)
    end
end

-- draw a texture into an absolute screen rect (scale=0 -> exact x2/y2)
local function put(id, rest, x, y, w, h, a, src, blend)
    if not id then return end
    tex.draw_texture(id, {
        x = x - rest[1], y = y - rest[2],
        scale = 0, x2 = w, y2 = h,
        fade = a, src = src, blend = blend,
    })
end

local ORIGIN = { 0, 0 }

-- ===== Z-DON AI battle start (the arcade's ai_song_select_before_load + enso_ai/loading/loading_ai) =====
-- Leaving the AI song select (is_second = false): the board dims, a teal VS window opens, the player's Don (left) and
-- the AI (right) slide in over "Now Loading...", which turns into "START!", a ring flashes and the screen goes black.
-- Then the game's own transition (is_second = true) shows the dark loading card with the title, subtitle and a hint.
-- Both are drawn from the instance (self.draw_bg / draw_info / state / update), so the normal transition is untouched.
local AI_VS_MS   = 3000
local AI_LOAD_MS = 3250   -- the loading card: intro, hold to 2600, gone at 2700, black to 2950, then the game fades in
local CARD_HOLD_END, CARD_GONE, CARD_REVEAL = 2600, 2700, 2950
local AI_T = {}
local function ai_tex(name)
    local t = AI_T[name]
    if not t then t = tex.get_texture("global/ai_transition/" .. name); AI_T[name] = t or nil end   -- loaded on demand: not cached while missing
    return t or nil
end
local function ai_info(name)
    return tex.get_texture_info("ai_transition", name) or tex.get_texture_info("global/ai_transition", name)
end
local function e_out(t) t = clamp(t, 0, 1); return 1 - (1 - t) * (1 - t) end
local function e_io(t) t = clamp(t, 0, 1); return t * t * (3 - 2 * t) end

local ai_txt = {}
local function ai_text(s, size, th, maxw, color, outline, font)
    color = color or { 255, 255, 255, 255 }
    outline = outline or { 0, 0, 0, 255 }
    local key = s .. "|" .. size .. "|" .. color[1] .. "|" .. outline[1] .. "|" .. (font or "")
    local t = ai_txt[key]
    if t == nil then
        t = false
        if s ~= "" and text and text.create_raw_text then
            local sz = size
            t = text.create_raw_text(s, sz, color, outline, false, th, 1.0, 1.0, font) or false
            while t and maxw and t.width > maxw and sz > 20 do
                sz = sz - 4
                t = text.create_raw_text(s, sz, color, outline, false, th, 1.0, 1.0, font) or false
            end
        end
        ai_txt[key] = t
    end
    return t or nil
end
local function ai_text_c(t, cx, cy, fade)
    if t then t:draw({ x = math.floor(cx - t.width / 2 + 0.5), y = math.floor(cy - t.height / 2 + 0.5), fade = fade }) end
end
-- draw a texture of the ai_transition folder centred on (cx, cy)
local function ai_put(name, cx, cy, sx, sy, fade)
    local t, i = ai_tex(name), ai_info(name)
    if not (t and i) then return end
    sx = sx or 1; sy = sy or sx
    tex.draw_texture(t, { x = cx - i.width * sx / 2, y = cy - i.height * sy / 2, scale = 0,
                          x2 = i.width * sx, y2 = i.height * sy, fade = fade or 1 })
end
local function ai_black(a)
    a = clamp(a, 0, 1)
    if a > 0.002 then tex.draw_rect(0, 0, 1920, 1080, 0, 0, 0, 255 * a) end
end

