-- round 3 (official-asset cleanup): the VS window is the raw shapes of ai_song_select_before_load placed by the movie's own
-- timeline (VS_TL above, frame = ms * 60 / 1000): dim, window, zig-zag lines, ring, label (dark -> teal), progress bar (the
-- shape's own colour), corners, flash, light beams. Only the Dons, the robot and the two text strings are ours.
local TX_LOADING, TX_START = { 789, 499 }, { 867, 509 }
local TX_LANG = { ja = 0, en = 1, ko = 2, tw = 3, zh = 4 }   -- jp en kr tw cn glyph sets
local function ai_tx_frame()
    local ok, l = pcall(function() return tex.language() end)
    local f = (ok and TX_LANG[l]) or 0
    if f == 4 then f = 3 end
    return f
end
local function ai_tx_put(name, o, fade)
    local t = ai_tex(name)
    if not t then return false end
    tex.draw_texture(t, { x = o[1], y = o[2], frame = ai_tx_frame(), fade = fade })
    return true
end

local function vs_item(it, f)
    local i = f - it.f0
    local n = #it.v / 6
    if i < 0 then return end
    if i >= n then
        if it.tex ~= "vs_dim" then return end   -- the black dim holds on its last frame
        i = n - 1
    end
    local k = i * 6
    local v = it.v
    local a = v[k + 6]
    if a <= 0.002 then return end
    local t, inf = ai_tex(it.tex), ai_info(it.tex)
    if not (t and inf) then return end
    local w, h = inf.width * v[k + 3], inf.height * v[k + 4]
    if w < 0.5 or h < 0.5 then return end
    local p = { x = v[k + 1] - w / 2, y = v[k + 2] - h / 2, scale = 0, x2 = w, y2 = h, fade = a }
    if it.tex == "vs_bar" then p.x = v[k + 1] end   -- the bar's shape grows from its left edge (734..1185, centred on the label)
    local rot = v[k + 5]
    if it.mir == "hv" then rot = 180
    elseif it.mir == "h" then p.mirror = "horizontal"
    elseif it.mir == "v" then p.mirror = "vertical" end
    if rot ~= 0 then
        p.x, p.y = v[k + 1], v[k + 2]
        p.rotation = rot
        p.origin = { w / 2, h / 2 }
    end
    tex.draw_texture(t, p)
end

local VS_CHARA_S, VS_CHARA_ROT = 1.25, 20   -- the loading window's 3D Dons

local function ai_vs_draw(self)
    local t = self.t or 0
    local f = math.floor(t * 60 / 1000)
    -- the window opens on movie frame 24
    -- the arcade's two loading cues: running as the bar grows (movie f42), finish on START (f76)
    local function cue(flag, at, name)
        if f >= at and not self[flag] then
            self[flag] = true
            if audio and audio.has_sound and audio.has_sound(name) then audio.play_sound(name, "sound") end
        end
    end
    cue("vs_cue_running", 42, "ai_loading_running")
    cue("vs_cue_finish", 76, "ai_loading_finish")
    for _, it in ipairs(VS_TL) do
        if it.tex ~= "vs_corner" and it.tex ~= "vs_s34" and it.tex ~= "vs_beam" and it.tex ~= "vs_bar" then vs_item(it, f) end
    end
    -- the two sides are uncovered from the bottom up by the rising beam and go with the window's close
    -- (arcade capture MBAZD6xA1D8: beam y 695 at f48, 16 px a frame; gone at f153)
    local vs_3d = (tex.get_option("ai_loading_chara_3d") or not tex.ai_active) and tex.ai_vs_chara_draw
    if vs_3d and f < 42 then tex.ai_vs_chara_load() end   -- ahead of its first frame
    if vs_3d and f >= 153 then tex.ai_vs_chara_release() end
    if vs_3d and f >= 42 and f < 153 then
        -- the cabinet's 3D Dons, uncovered by the same beam (direct feed 0wD5kkcN5WA 1:52: ~384 / ~1526, feet about y 747)
        local wipe_y = clamp(math.floor(695 - (f - 48) * 16.1), 0, 1080)
        local bob3d = math.sin(t / 260) * 4
        tex.begin_scissor(0, wipe_y, 1920, 1080 - wipe_y)
        tex.ai_vs_chara_draw(0, 384, 747 + bob3d, VS_CHARA_S, VS_CHARA_ROT)
        tex.ai_vs_chara_draw(1, 1526, 747 - bob3d, VS_CHARA_S, -VS_CHARA_ROT)
        tex.end_scissor()
    elseif f >= 42 and f < 153 then
        local wipe = 695 - (f - 48) * 16.1
        local bob = math.sin(t / 260) * 4
        -- the player's Don (the skin's own 2D Don of the rainbow loading; the cabinet seats the 3D Don here; the old
        -- vs_don art was a placeholder box) on the left, the robot on the right (direct feed 0wD5kkcN5WA 1:50: ~400 / ~1520)
        local dc = self.chara_l
        if dc then
            local dsz, y0 = 480, 570 + bob - 240   -- round 3a: the arcade's costumed Don fills about 200 x 190 of the 1000 px sheet (ours was 150 x 142)
            local cut = clamp(wipe - y0, 0, dsz)
            if cut < dsz then
                local di = tex.get_texture_info("global/rainbow_transition", "chara_left")
                    or tex.get_texture_info("rainbow_transition", "chara_left")
                local sw, sh = di and di.width or 560, di and di.height or 560
                put(dc, REST_CHARA_L, 384 - dsz / 2, y0 + cut, dsz, dsz - cut, 1,
                    { x = 0, y = sh * cut / dsz, width = sw, height = sh * (1 - cut / dsz) })
            end
        end
        local rt, ri = ai_tex("vs_robot"), ai_info("vs_robot")   -- direct feed 0wD5 1:52: robot about 332 px tall, centre (1526, 570)
        if rt and ri then
            local w, h = ri.width * 0.73, ri.height * 0.73
            local y0 = 570 - bob - h / 2
            local cut = clamp(wipe - y0, 0, h)
            if cut < h then
                tex.draw_texture(rt, { x = 1526 - w / 2, y = y0 + cut, scale = 0, x2 = w, y2 = h - cut,
                                       src = { x = 0, y = ri.height * cut / h, width = ri.width, height = ri.height * (1 - cut / h) } })
            end
        end
    end
    -- txt_loading (movie frames 42..75, over the dark label) / txt_start (76..)
    local la = clamp((f - 42) / 8, 0, 1)
    -- the cabinet's own lettering (txt_derivation, wordlist ai_song_select_derivation_loading / _start, rendered with the
    -- glyph atlases and baked as black + alpha: tx_loading / tx_start, frame = language), at the movie's stage position
    if f >= 153 then
        -- the label's text goes with the sides, only the bar closes
    elseif f >= 76 then
        if not ai_tx_put("tx_start", TX_START, 1) then
            ai_text_c(ai_text("START!", 38, 0, 600, { 0, 0, 0, 255 }), 960, 540, 1)
        end
    elseif f >= 42 then
        if not ai_tx_put("tx_loading", TX_LOADING, la) then
            ai_text_c(ai_text("Now Loading...", 44, 0, 500, { 0, 0, 0, 255 }), 957, 528, la)
        end
    end
    for _, it in ipairs(VS_TL) do
        if it.tex == "vs_bar" or it.tex == "vs_corner" or it.tex == "vs_s34" or it.tex == "vs_beam" then vs_item(it, f) end
    end
    if t >= 2917 then ai_black(1) end
end

local function ai_card_draw(self)
    local t = self.t or 0
    require("global.ai_battle").card_up()   -- the floor's opening waits for the card
    if t >= CARD_GONE then
        ai_black(1 - clamp((t - CARD_REVEAL) / (AI_LOAD_MS - CARD_REVEAL), 0, 1))   -- black, then the game fades in
        return
    end
    ai_black(1)
    local a = 1 - clamp((t - CARD_HOLD_END) / (CARD_GONE - CARD_HOLD_END), 0, 1)
    -- the arcade's loading movie (loading_ai): the intro (frames 5..27, every 2nd: 12 baked), then its 120-frame
    -- background loop (every 3rd: 40 baked); the still card when absent
    local c = ai_tex("card")
    if ai_tex("lt_card_1_0") then
        -- from the movie's own tracks: the intro to frame 27, then its 120-frame background loop
        local m = 5 + t * 0.06
        if m >= 147 then m = 27 + (m - 27) % 120 end
        require("global.lumen_tracks").draw(require("global.ai_fx_card"), m, function(n) local q = ai_tex(n); return q and { t = q } end, 0, 0, 1, a)
    elseif c then
        tex.draw_texture(c, { x = 0, y = 0, scale = 0, x2 = 1920, y2 = 1080, fade = a * clamp(t / 350, 0, 1) })
    end
    if t < 130 then return end   -- the skip badge comes with the intro's background, the text with its frame
    -- 演奏スキップON badge (the card's own pill is drawn empty)
    if self:skip_armed() and self.skip_badge then
        put(self.skip_badge, SKIP_REST, SKIP_BADGE_X, SKIP_BADGE_Y, 624, 104, a)
        if self.skip_text then
            self.skip_text:draw({ x = SKIP_BADGE_CX - self.skip_text.width / 2,
                                  y = SKIP_TEXT_CY - self.skip_text.height / 2, fade = a })
        end
    end
    if t < 320 or t >= CARD_HOLD_END then return end
    a = 1
    local TITLE, RIM, GOTHIC = { 255, 255, 255, 255 }, { 38, 150, 160, 255 }, "FOT-Seurat_Pro_B.otf"
    ai_text_c(ai_text(self.ai_title or "", 64, 4, 1500, TITLE, RIM), 960, 449, a)   -- round 3a: ink centre 444.5 in the direct feed (was 423.5)
    ai_text_c(ai_text(self.ai_subtitle or "", 40, 3, 1500, TITLE, RIM), 960, 538, a)   -- round 3a: direct feed ink centre 537.5 (YOASOBI)
    local function skin(k) local s = tex.skin_text(k); return (s and s ~= "") and s or "" end
    ai_text_c(ai_text(skin("transition_hint_title"), 32, 3, 900, nil, nil, GOTHIC), 960, 743, a)
    ai_text_c(ai_text(skin("ai_load_tip_1"), 32, 3, 1300, nil, nil, GOTHIC), 960, 808, a)
    ai_text_c(ai_text(skin("ai_load_tip_2"), 32, 3, 1300, nil, nil, GOTHIC), 960, 859, a)
end

ai_setup = function(self, title, subtitle)
    if self.is_second then   -- load the card's shapes now, not on its first frame
        for _, q in ipairs(require("global.ai_fx_card").pieces) do ai_tex(q.t) end
    end
    -- the folder is unloaded with its screen and only get_texture loads it again: cached handles would keep the
    -- drawing going while get_texture_info finds nothing (window, ring and robot gone on the next battle)
    AI_T = {}
    self.ai, self.ai_title, self.ai_subtitle = true, title, subtitle
    self.draw_bg = function(s) if s.is_second then ai_card_draw(s) else ai_vs_draw(s) end end
    self.draw_info = function() end
    self.state = function(s)
        local t = s.t or 0
        if s.is_second then return { rainbow_up = 0, fade = 1, fade_out = 1, finished = t >= AI_LOAD_MS } end
        return { rainbow_up = 0, fade = 0, finished = t >= AI_VS_MS }
    end
    self.update = function(s, current_ms)
        if not s.t0 then s.t0 = current_ms end
        s.t = current_ms - s.t0
    end
end
-- ===== end AI battle start =====



function SongTransition:draw_bg(total_offset, rainbow_up, mini_up, chara_down)
    local f = self.f

    -- 1. backdrop: two curved curtains, or the flat full-screen rainbow
    if f >= F_FULL_A and f <= F_FULL_B then
        put(self.rainbow, ORIGIN, 0, 0, 1920, 1080, 1)
    else
        local lx = track("#47@0", f, "tx", -240)
        local ls = track("#47@0", f, "sx", 0.5)
        local rx = track("#49@1", f, "tx", 2160)
        local rs = track("#49@1", f, "sx", 0.5)
        put(self.atlas_c, ORIGIN, lx - 480 * ls, 0, 960 * ls, 1080, 1, SRC_CURT_L)
        put(self.atlas_c, ORIGIN, rx - 480 * rs, 0, 960 * rs, 1080, 1, SRC_CURT_R)
    end

    -- 2. glow along the bottom: the cabinet's own black-backed atlas piece, added onto the backdrop
    local ga = track("#55@3", f, "a", 0)
    if ga > 0.002 then
        put(self.atlas_b, ORIGIN, 0, 568, 1920, 512, ga, SRC_GLOW, "additive")
    end

    -- 3. the eleven sparkles — fixed placements, one group alpha
    local sa = track("#3@4", f, "a", 0)
    if sa > 0.002 then
        for i = 1, #STARS do
            local s = STARS[i]
            local d = 128 * s[3]
            put(self.atlas_b, ORIGIN, s[1] - d * 0.5, s[2] - d * 0.5, d, d, sa, SRC_STAR)
        end
    end

    -- 4. don / katsu on their arc
    local da = track("don", f, "a", 1)
    if da > 0.002 and not self.wash then
        put(self.chara_l, REST_CHARA_L,
            track("don", f, "tx", 160) - 280, track("don", f, "ty", 786) - 280,
            560, 560, da)
    end
    local ka = track("katsu", f, "a", 1)
    if ka > 0.002 and not self.wash then
        put(self.chara_r, REST_CHARA_R,
            track("katsu", f, "tx", 1760) - 280, track("katsu", f, "ty", 786) - 280,
            560, 560, ka)
    end

    -- 5. the title band (opens/closes on the engine's title fade)
    local info = self.info
    if info > 0.002 then
        local bw, bh
        if self.is_second then
            bw = 1600 * (1.5 - 0.5 * info)
            bh =  256 * (0.1 + 0.9 * info)
        else
            bw = 1600 * (0.25 + 0.75 * info)
            bh =  256
        end
        put(self.atlas_b, ORIGIN, 960 - bw * 0.5, 400 - bh * 0.5, bw, bh, info, SRC_BAND)
        -- 6. the hint block on the same curve (or the wash-your-hands card, loading_song 'washhands' at 960,810)
        if self.wash then
            local wt = tex.get_texture("global/loading_hint/washhands")
            local wi = tex.get_texture_info("loading_hint", "washhands") or tex.get_texture_info("global/loading_hint", "washhands")
            if wt and wi then
                put(wt, ORIGIN, 289, 559, wi.width, wi.height, info)
                if text and text.create_raw_text then
                    self.wash_text = self.wash_text or text.create_raw_text(tex.skin_text("wash_hands_text") or "", 40,
                        { 59, 170, 214, 255 }, { 255, 255, 255, 255 }, false, 5, 1.0)
                    local t = self.wash_text
                    if t then t:draw({ x = math.floor(960 - t.width / 2), y = math.floor(640 - t.height / 2), fade = info }) end
                end
            end
        elseif self.hint_title then
            -- texture rows, all centred on x = 960
            local function centred(t, y)
                if t then t:draw({ x = math.floor(960 - t.width / 2 + 0.5), y = y, fade = info }) end
            end
            centred(self.hint_title, 568 + 165)
            centred(self.hint_line1, 568 + 228)
            centred(self.hint_line2, 568 + 282)
        else
            put(self.hint, REST_HINT, 0, 568, 1920, 512, info)
        end
    end

    -- 7. 演奏スキップON badge, top-left, on the same fade
    if self:skip_armed() and self.skip_badge then
        put(self.skip_badge, SKIP_REST, SKIP_BADGE_X, SKIP_BADGE_Y, 624, 104, info)
        if self.skip_text then
            self.skip_text:draw({
                x = SKIP_BADGE_CX - self.skip_text.width / 2,
                y = SKIP_TEXT_CY - self.skip_text.height / 2,
                fade = info,
            })
        end
    end
end
